70	/**
71	 * Compute the hash drizzle-orm stores for a migration file.
72	 * Drizzle uses SHA-256 of the raw file content (not split statements).
73	 * Returns null if the SQL file does not exist on disk.
74	 */
75	function migrationHash(tag: string): string | null {
76	  const filePath = path.join('drizzle', `${tag}.sql`);
77	  if (!fs.existsSync(filePath)) return null;
78	  const content = fs.readFileSync(filePath).toString();
79	  return crypto.createHash('sha256').update(content).digest('hex');
80	}
